"""Helpers for building the Review-2 deck from the PWP1 template."""
import copy
from pptx.oxml.ns import nsdecls, qn
from pptx.oxml import parse_xml
from pptx.util import Emu, Pt

TNR = 'Times New Roman'
PANOSE = 'panose="02020603050405020304" pitchFamily="18" charset="0"'


def clone_slide(prs, src_idx):
    src = prs.slides[src_idx]
    new = prs.slides.add_slide(src.slide_layout)
    for shp in list(new.shapes):
        shp._element.getparent().remove(shp._element)
    for shp in src.shapes:
        new.shapes._spTree.append(copy.deepcopy(shp._element))
    return new


def set_title(slide, text, size=32):
    sh = slide.shapes[0]
    tf = sh.text_frame
    body = tf._txBody
    for p in body.findall(qn('a:p')):
        body.remove(p)
    xml = (
        '<a:p %s><a:pPr algn="ctr"/><a:r><a:rPr lang="en-IN" sz="%d" b="1" dirty="0">'
        '<a:latin typeface="%s" %s/><a:cs typeface="%s" %s/></a:rPr>'
        '<a:t>%s</a:t></a:r></a:p>' % (nsdecls('a'), int(size * 100), TNR, PANOSE, TNR, PANOSE, esc(text))
    )
    body.append(parse_xml(xml))


def esc(t):
    return (t.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;'))


def _run_xml(text, size, bold, color='000000', italic=False):
    return (
        '<a:r><a:rPr lang="en-IN" sz="%d" b="%d" i="%d" dirty="0">'
        '<a:solidFill><a:srgbClr val="%s"/></a:solidFill>'
        '<a:latin typeface="%s" %s/><a:cs typeface="%s" %s/></a:rPr>'
        '<a:t xml:space="preserve">%s</a:t></a:r>'
        % (int(size * 100), 1 if bold else 0, 1 if italic else 0, color, TNR, PANOSE, TNR, PANOSE, esc(text))
    )


def set_body(shape, items, size=14, bullet=True, justify=True, space_after=4,
             indent=368300, line_spacing=None):
    """items: list of paragraphs. Each paragraph is a string, or a list of
    (text, bold) / (text, bold, color) tuples."""
    tf = shape.text_frame
    body = tf._txBody
    for p in body.findall(qn('a:p')):
        body.remove(p)
    algn = 'just' if justify else 'l'
    for item in items:
        if isinstance(item, str):
            parts = [(item, False)]
        else:
            parts = item
        bu = ('<a:buFont typeface="Arial" panose="020B0604020202020204" pitchFamily="34" charset="0"/>'
              '<a:buChar char="•"/>') if bullet else '<a:buNone/>'
        ls = '<a:lnSpc><a:spcPct val="%d"/></a:lnSpc>' % int(line_spacing * 1000) if line_spacing else ''
        runs = ''.join(_run_xml(p[0], size, p[1], p[2] if len(p) > 2 else '000000') for p in parts)
        xml = ('<a:p %s><a:pPr marL="%d" indent="%d" algn="%s">%s<a:spcAft><a:spcPts val="%d"/></a:spcAft>%s</a:pPr>%s</a:p>'
               % (nsdecls('a'), indent, -indent if bullet else 0, algn, ls, int(space_after * 100), bu, runs))
        body.append(parse_xml(xml))


def set_cell(cell, text, size=9, bold=False, align='l'):
    tf = cell.text_frame
    body = tf._txBody
    for p in body.findall(qn('a:p')):
        body.remove(p)
    for line in str(text).split('\n'):
        xml = ('<a:p %s><a:pPr algn="%s"/>%s</a:p>'
               % (nsdecls('a'), align, _run_xml(line, size, bold)))
        body.append(parse_xml(xml))
    cell.margin_left = Emu(45720)
    cell.margin_right = Emu(45720)
    cell.margin_top = Emu(18288)
    cell.margin_bottom = Emu(18288)


def set_rows(table, n):
    """Grow/shrink a table to n rows by cloning the last row."""
    tbl = table._tbl
    trs = tbl.findall(qn('a:tr'))
    while len(trs) > n:
        tbl.remove(trs[-1])
        trs = tbl.findall(qn('a:tr'))
    while len(trs) < n:
        new = copy.deepcopy(trs[-1])
        tbl.append(new)
        trs = tbl.findall(qn('a:tr'))
    return table


def find_tables(slide):
    return [sh for sh in slide.shapes if sh.has_table]


def drop_slides(prs, keep_ids):
    """keep_ids: list of slide ids (in desired order) to keep."""
    sldIdLst = prs.slides._sldIdLst
    entries = list(sldIdLst)
    by_id = {e.get('id'): e for e in entries}
    for e in entries:
        sldIdLst.remove(e)
    for sid in keep_ids:
        sldIdLst.append(by_id[sid])
    # drop orphan rels
    keep_rids = {by_id[s].get(qn('r:id')) for s in keep_ids}
    for e in entries:
        rid = e.get(qn('r:id'))
        if rid not in keep_rids:
            try:
                prs.part.drop_rel(rid)
            except Exception:
                pass

