# -*- coding: utf-8 -*-
"""Estimate text overflow using real Times New Roman metrics (no renderer needed)."""
import sys
from pptx import Presentation
from pptx.util import Emu
from PIL import ImageFont

EMU_IN = 914400
PT_EMU = 12700
FONT_PATH = r'C:\Windows\Fonts\times.ttf'
BOLD_PATH = r'C:\Windows\Fonts\timesbd.ttf'
_cache = {}


def font(sz, bold):
    key = (round(sz), bold)
    if key not in _cache:
        _cache[key] = ImageFont.truetype(BOLD_PATH if bold else FONT_PATH, max(int(round(sz * 4)), 4))
    return _cache[key]


def width_pt(text, sz, bold):
    f = font(sz, bold)
    return f.getlength(text) / 4.0  # we rendered at 4x pt size


def wrap_lines(runs, avail_pt):
    """runs: list of (text, size_pt, bold). Returns line count and max size."""
    words = []
    for text, sz, bold in runs:
        for w in text.split(' '):
            if w:
                words.append((w, sz, bold))
    if not words:
        return 1, max([r[1] for r in runs], default=12)
    lines, cur = 1, 0.0
    space = width_pt(' ', words[0][1], False)
    for w, sz, bold in words:
        ww = width_pt(w, sz, bold)
        add = ww if cur == 0 else ww + space
        if cur + add > avail_pt and cur > 0:
            lines += 1
            cur = ww
        else:
            cur += add
    return lines, max(r[1] for r in words)


def tf_height_pt(tf, box_w_emu):
    avail = (box_w_emu - tf.margin_left - tf.margin_right) / PT_EMU
    total = 0.0
    for para in tf.paragraphs:
        marL = para._pPr.get('marL') if para._pPr is not None else None
        indent_pt = (int(marL) / PT_EMU) if marL else 0
        runs = [(r.text, (r.font.size.pt if r.font.size else 14), bool(r.font.bold)) for r in para.runs]
        if not runs:
            total += 14 * 1.2
            continue
        n, sz = wrap_lines(runs, max(avail - indent_pt, 20))
        spc = para._pPr.find(
            '{http://schemas.openxmlformats.org/drawingml/2006/main}spcAft') if para._pPr is not None else None
        after = 0.0
        if spc is not None:
            pts = spc.find('{http://schemas.openxmlformats.org/drawingml/2006/main}spcPts')
            if pts is not None:
                after = int(pts.get('val')) / 100.0
        total += n * sz * 1.21 + after
    return total


def main(path):
    prs = Presentation(path)
    SH = prs.slide_height
    problems = []
    for i, s in enumerate(prs.slides, 1):
        if i <= 2:
            continue
        for sh in s.shapes:
            if sh.has_text_frame and sh.text_frame.text.strip() and sh.height and sh.height > 900000:
                need = tf_height_pt(sh.text_frame, sh.width) + (sh.text_frame.margin_top + sh.text_frame.margin_bottom) / PT_EMU
                have = sh.height / PT_EMU
                room = (SH - sh.top) / PT_EMU - 8
                cap = min(have, room)
                if need > cap:
                    problems.append((i, 'textbox', round(need, 1), round(cap, 1), round(need - cap, 1)))
            if sh.has_table:
                tbl = sh.table
                widths = [c.width for c in tbl.columns]
                total = 0.0
                for r, row in enumerate(tbl.rows):
                    hmax = 0.0
                    for c, cell in enumerate(row.cells):
                        need = tf_height_pt(cell.text_frame, widths[c]) + \
                            (cell.margin_top + cell.margin_bottom) / PT_EMU
                        hmax = max(hmax, need)
                    total += max(hmax, row.height / PT_EMU)
                room = (SH - sh.top) / PT_EMU - 8
                if total > room:
                    problems.append((i, 'table', round(total, 1), round(room, 1), round(total - room, 1)))
    if not problems:
        print('OK - no estimated overflow')
    for p in problems:
        print('slide %-3d %-8s needs %.1fpt, room %.1fpt, OVER by %.1fpt' % p)
    print('total flagged:', len(problems))


if __name__ == '__main__':
    main(sys.argv[1])

